static class BridgeProtocolChecks {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static void Masked(Stream stream,int opcode,string text){byte[] bytes=Encoding.UTF8.GetBytes(text);Check(bytes.Length<126,"Fixture is too large");var frame=new byte[bytes.Length+6];frame[0]=(byte)(0x80|opcode);frame[1]=(byte)(0x80|bytes.Length);for(int i=0;i<4;i++)frame[i+2]=(byte)(i+1);for(int i=0;i<bytes.Length;i++)frame[i+6]=(byte)(bytes[i]^frame[i%4+2]);stream.Write(frame,0,frame.Length);}
 static string Reply(Stream stream,out int opcode){var prefix=BridgeWire.Read(stream,2);opcode=prefix[0]&15;int count=prefix[1]&127;if(count==126){var size=BridgeWire.Read(stream,2);count=(size[0]<<8)|size[1];}Check(count<65536,"Unexpected fixture length");return Encoding.UTF8.GetString(BridgeWire.Read(stream,count));}
 static string Reply(Stream stream){int opcode;return Reply(stream,out opcode);}
 static TcpClient Open(int port,string path,out string response){var client=new TcpClient();client.Connect("127.0.0.1",port);client.ReceiveTimeout=3000;client.SendTimeout=3000;var stream=client.GetStream();var request=Encoding.ASCII.GetBytes("GET "+path+" HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: MDEyMzQ1Njc4OWFiY2RlZg==\r\n\r\n");stream.Write(request,0,request.Length);var header=new StringBuilder();while(header.Length<8192){int next=stream.ReadByte();if(next<0)break;header.Append((char)next);if(header.ToString().EndsWith("\r\n\r\n"))break;}response=header.ToString();return client;}
 public static void Run(){int captures=0;var hub=new BridgeHub();using(var server=new BarBridgeServer(hub,text=>"reply:"+text,()=>{Interlocked.Increment(ref captures);hub.Publish("during");return new[]{"font","appearance","channels"};},line=>line=="GET /fixture HTTP/1.1",text=>{},0)){
