   Masked(stream,1,"subscribe");Check(Reply(stream)=="reply:subscribe"&&captures==1,"Repeated subscribe not idempotent");Masked(stream,9,"ping-body");int opcode;Check(Reply(stream,out opcode)=="ping-body"&&opcode==10,"Pong payload/opcode changed");Masked(stream,1,"audio-status");Check(Reply(stream)=="reply:audio-status","Dispatch round-trip failed");Masked(stream,8,"");Check(Reply(stream,out opcode)==""&&opcode==8,"Close handshake failed");
  }
  Check(SpinWait.SpinUntil(()=>hub.Count==0,3000),"Disconnected connection retained");
  using(var client=Open(server.Port,"/fixture",out response)){var stream=client.GetStream();Masked(stream,1,"widgets");for(int i=0;i<5;i++)Reply(stream);Check(captures==2,"Legacy widgets/reconnect did not receive fresh initial state");server.Dispose();Check(SpinWait.SpinUntil(()=>server.ClientCount==0&&hub.Count==0,3000),"Listener disposal retained clients");}
 }
  bool rejected=false;try{BridgeWire.ReadFrame(new MemoryStream(new byte[]{0x81,0x00}));}catch(IOException){rejected=true;}Check(rejected,"Unmasked client frame accepted");
  rejected=false;try{BridgeWire.ReadFrame(new MemoryStream(new byte[]{0x81,0xff,0,0,0,0,0,8,0,1}));}catch(IOException){rejected=true;}Check(rejected,"Oversized frame accepted");
  foreach(int length in new[]{126,65536})using(var packet=new MemoryStream()){
   packet.WriteByte(0x81);packet.WriteByte((byte)(0x80|(length<65536?126:127)));if(length<65536){packet.WriteByte((byte)(length>>8));packet.WriteByte((byte)length);}else for(int shift=56;shift>=0;shift-=8)packet.WriteByte((byte)((long)length>>shift));
   packet.Write(new byte[]{1,2,3,4},0,4);for(int i=0;i<length;i++)packet.WriteByte((byte)('a'^(i%4+1)));packet.Position=0;var frame=BridgeWire.ReadFrame(packet);Check(frame.Bytes.Length==length&&frame.Bytes.All(b=>b=='a'),"Extended length/mask decoding changed");
  }
  int routed=0;var router=new BridgeCommandRouter(command=>{routed++;return command.Kind+"|"+command.Value;},text=>{});Check(router.Receive("task-context:{\"id\":1}")=="TaskContext|{\"id\":1}","Typed task routing lost arguments");Check(router.Receive("audio-volume:25")=="Audio|volume:25","Audio compatibility route changed");Check(router.Receive("garbage")=="{\"ok\":false}"&&routed==2,"Unknown command reached application");int x,y;Check(BridgeCommand.Parse("power-preview:-1920:25").Coordinates(out x,out y)&&x==-1920&&y==25&&!BridgeCommand.Parse("power:bad:2").Coordinates(out x,out y),"Power coordinate parsing changed");
  bool logged=false;var failing=new BridgeCommandRouter(command=>{throw new IOException("fixture");},text=>logged=text.Contains("Audio"));Check(failing.Receive("audio-status")=="{\"ok\":false}"&&logged,"Dispatch failures not isolated/logged");
  Check(BridgeCommand.Parse("  {\"title\":\"Song\"}").Kind==BridgeCommandKind.Metadata,"Whitespace-prefixed metadata compatibility changed");
  DateTime now=new DateTime(2026,11,3);var metadata=new MediaMetadataStore(()=>now);Check(metadata.Receive("{\"url\":\"https://open.spotify.com/track/fixture\",\"title\":\"Song\",\"album\":\"Album\"}").Contains("true")&&metadata.Context("Song")[0]=="Album","Metadata adapter lost context");Check(metadata.Receive("{\"url\":\"https://example.com/track/fixture\",\"title\":\"Other\"}").Contains("false")&&metadata.Current("Other")==null,"Invalid metadata replaced valid state");now=now.AddSeconds(46);Check(metadata.Current("Song")==null,"Metadata freshness changed");
  now=now.AddSeconds(1);metadata.Receive("{\"url\":\"https://open.spotify.com/track/song1\",\"title\":\"Links\",\"playlistUrl\":\"https://open.spotify.com/playlist/list1\",\"albumUrl\":\"https://open.spotify.com/album/album1\"}");var links=metadata.Links("Links");Check(links.Combined=="Song: https://open.spotify.com/track/song1 | Artist: NA | Playlist: https://open.spotify.com/playlist/list1 | Album: https://open.spotify.com/album/album1"&&MediaCard.CopyText(links,1)==links.Song&&MediaCard.CopyText(links,2)==links.Playlist&&MediaCard.CopyText(links,3)==links.Album,"Spotify copy components or order incorrect");
  metadata.Receive("{\"url\":\"https://open.spotify.com/track/song2\",\"title\":\"Missing\",\"albumUrl\":\"https://example.com/album/a\"}");Check(metadata.Links("Missing").Combined=="Song: https://open.spotify.com/track/song2 | Artist: NA | Playlist: NA | Album: NA"&&metadata.Links("Links").Song==null,"Unavailable or invalid context links must not reuse old context");now=now.AddSeconds(46);Check(metadata.Links("Missing").Combined=="Song: NA | Artist: NA | Playlist: NA | Album: NA","Stale Spotify links were retained");
  metadata.Receive("{\"url\":\"https://open.spotify.com/track/artistSong\",\"title\":\"Artist song\",\"artistUrl\":\"https://open.spotify.com/artist/Artist123\",\"shuffle\":\"true\"}");Check(metadata.Links("Artist song").Artist=="https://open.spotify.com/artist/Artist123"&&metadata.Links("Artist song").Combined=="Song: https://open.spotify.com/track/artistSong | Artist: https://open.spotify.com/artist/Artist123 | Playlist: NA | Album: NA"&&MediaCard.CopyText(metadata.Links("Artist song"),4)=="https://open.spotify.com/artist/Artist123"&&metadata.Shuffle("Artist song")==true&&MediaCard.ArtistPage("https://example.com/artist/bad")==null,"Artist page validation or shuffle state failed");now=now.AddSeconds(46);Check(metadata.Shuffle("Artist song")==null&&metadata.Links("Artist song").Artist==null,"Stale artist/shuffle metadata leaked to a different session");
  Console.WriteLine("PASS: isolated ephemeral-loopback auth, subscription/reconnect barrier, legacy widgets, ping/pong/close, listener disposal, frame limits, typed routing and metadata validation. No production ports or desktop actions.");
